//#region resources/js/types.ts
function formatPrice(cents, market) {
	try {
		return new Intl.NumberFormat(market.hrefLang, {
			style: "currency",
			currency: market.currency
		}).format(cents / 100);
	} catch {
		return (cents / 100).toFixed(2);
	}
}
